   deg=sum((r+dr,c+dc) in idx and idx[(r+dr,c+dc)]==i for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)])
   if deg<=1: endpoints.append((i,r,c))
 out=[row[:] for row in grid]; coords=set()
 # Each line: consecutive endpoints; can skip same component pairs by searching nearest differing component on both sides
 for axis in [0,1]:
  lines={}
  for i,r,c in endpoints:
   key=r if axis==0 else c
   pos=c if axis==0 else r
   lines.setdefault(key,[]).append((pos,i))
  for key,arr in lines.items():
