      if abs(pos2-pos)<=maxd:
       for x in range(min(pos,pos2)+1,max(pos,pos2)):
        rc=(key,x) if axis==0 else (x,key)
        if grid[rc[0]][rc[1]]!=fg:coords.add(rc)
      break
 for r,c in coords:out[r][c]=2
 return out,coords,cs,endpoints
